"""Entry point for all telemetry Data"""

import logging
from json import JSONDecodeError
from typing import Dict, Union
from functools import wraps

import requests

from taf.ul.telemetry import settings
from taf.ul.telemetry.interface import Telemetry
from taf.ul.telemetry.instrumentation import get_telemetry_instruments
from taf.ul.telemetry.schema import Config
from taf.ul.telemetry.telemetry import BaseTelemetryAPI, NoOpTelemetryApi, TelemetryAPI
from taf.ul.telemetry.stack_inspect import get_service_name_from_stack
from taf.ul.telemetry.utils import disable_logging
logger = logging.getLogger(__name__)

_registry: Dict[str, Telemetry] = {}


def get_instance(service_name: str) -> Telemetry:
    """Get registered Telemetry instance by service name."""
    match = service_name.lower().replace('-', '_')
    while match:
        if match in _registry:
            return _registry[match]
        match = '.'.join(match.split('.')[:-1])
    logger.error(f"Service name '{service_name}' not in telemetry registry. Call telemetry_register first.")
    return Telemetry(NoOpTelemetryApi())


def register(
    service_name: str,
    metadata: Dict[str, Union[int, float, str]] = None,
) -> Telemetry:
    """The mian function to be used with telemetry which returns a Telemetry interface.

    First thing you need to do to use telemetry is to register your application with given service_name.
    Only then you will be able to use Telemetry API.

    :param service_name: service name taken from stack.
    :param metadata: An optional set of data describing your service - it will be attached to all telemetry data.
    :return: Telemetry interface to be used to report data.
    """
    logger.debug("Starting registration of service: %s", service_name)
    tracer, meter = get_telemetry_instruments()
    with tracer.start_as_current_span("register") as cur_span:
        cur_span.set_attribute("service_name", service_name)
        tl = _registry.get(service_name)

        if not tl:
            cur_span.add_event("Creating new instance")
            tl = _create_telemetry(service_name, metadata)
            tl = Telemetry(tl)
            if not isinstance(tl._telemetry, NoOpTelemetryApi):
                cur_span.add_event("Saving new instance")
                _registry[service_name] = tl
                with disable_logging("opentelemetry.sdk.metrics._internal"):
                    registration_count = meter.create_counter("taf.ul.telemetry_registration", "",
                                                              "Number of times register was successful")
                registration_count.add(1, {'service': service_name})
        return tl


def _create_telemetry(
    service_name: str, metadata: Dict[str, Union[int, float, str]] = None
) -> BaseTelemetryAPI:
    """Crete appropriate TelemetryAPI."""
    if settings._NOOP:
        logger.warning("Telemetry is disabled - cannot create instance of TelemetryAPI!")
        return NoOpTelemetryApi()
    metadata = metadata or {}
    _schema = _fetch_configuration(service_name)
    if _schema:
        _schema.resources.update(metadata)
        tl = TelemetryAPI(_schema)
        logger.debug("Telemetry Setup finished for '%s'. Data collection started.", service_name)
        return tl
    logger.warning("Config was not created, returning NoOp Telemetry")
    return NoOpTelemetryApi()


def _fetch_configuration(name: str):
    """Fetch service configuration from config service by given service name."""
    from opentelemetry import trace
    tracer, meter = get_telemetry_instruments()
    with tracer.start_as_current_span("fetch_config") as cur_span:
        logger.debug("Trying to fetch configuration for %s", name)
        config = None

        try:
            app_response = requests.post(
                settings._CONFIG_APP_ENDPOINT, timeout=1.5, json={"service_name": name}, headers={"X-SERVICE": "config"},
                proxies={'http': settings._PROXY_ENDPOINT}
            )
            if app_response.ok:
                config = Config(**app_response.json()["config"])
                if config.is_empty():
                    cur_span.set_status(trace.StatusCode.ERROR)
                    logger.warning("Configuration is empty for %s", name)
                    return None
                logger.debug("Configuration created for: %s", name)
            else:
                cur_span.set_status(trace.StatusCode.ERROR)
                logger.warning(
                    "Failed to fetch configuration for %s, from %s, status code: %d",
                    name,
                    settings._CONFIG_APP_ENDPOINT,
                    app_response.status_code,
                )

        except requests.exceptions.RequestException as exc:
            logger.warning("Exception raised while fetching configuration for %s", name)
            cur_span.record_exception(exc)
            cur_span.set_status(trace.StatusCode.ERROR)
        except JSONDecodeError as exc:
            logger.warning("Exception raised while decoding configuration for %s", name)
            cur_span.record_exception(exc)
            cur_span.set_status(trace.StatusCode.ERROR)
        return config


def telemetry_register(metadata=None):
    service_name = get_service_name_from_stack()
    tl = register(service_name, metadata)
    return tl


def telemetry_instance():
    service_name = get_service_name_from_stack()
    tl = get_instance(service_name)
    return tl


def trace(name=None, reraise=True):
    service_name = get_service_name_from_stack()

    def trace_decor(function):

        @wraps(function)
        def wrapper(*args, **kwargs):
            tl = get_instance(service_name)
            trace_name = function.__name__ if name is None else name
            with tl.trace(trace_name) as main_trace:
                try:
                    result = function(*args, **kwargs)
                    return result
                except Exception:
                    main_trace.set_status_error('Exception occurred during run')
                    if reraise:
                        raise
        return wrapper
    return trace_decor
